const sort=(id,items,zones,correct)=>{if(correct!==null)bind(id,correct,'sort');let v=vals[id]||items.map(()=>-1);if(!Array.isArray(v)||v.length!==items.length)v=items.map(()=>-1);let html=`<div class="sort-widget" data-sort="${id}"><div class="sort-pool" data-zone="-1">${items.map((x,i)=>v[i]===-1?`<button draggable="true" class="sort-chip" data-item="${i}" data-sortkey="${id}" type="button">${esc(x)}</button>`:'').join('')}</div><div class="grid3">`;zones.forEach((z,zi)=>{html+=`<div class="sort-zone" data-zone="${zi}" role="button" tabindex="0"><h4>${esc(z[0])}</h4><p>${esc(z[1]||'')}</p><div class="zone-chips">${items.map((x,i)=>v[i]===zi?`<button draggable="true" type="button" data-sortkey="${id}" data-item="${i}" class="sort-chip">${esc(x)}</button>`:'').join('')}</div></div>`});html+='</div><p class="sort-note">Drag each topic into a category, or tap a topic and then tap its destination. Tap a placed topic to return it.</p></div>';return html};
